function t(key, lang) {
  const entry = STR[key];
  if (!entry) return key;
  return entry[lang] || entry.en || key;
}

function opt(listKey, lang) {
  const list = OPTIONS[listKey] || [];
  return list.map(o => ({ key: o.key, label: o[lang] || o.en, weight: o.weight }));
}

function optLabel(listKey, key, lang) {
  const list = OPTIONS[listKey] || [];
  const found = list.find(o => o.key === key);
  return found ? (found[lang] || found.en) : key;
}
